import { useState } from 'react'

const initialTodos = ['梳理需求', '生成代码', '应用 Diff']

export default function App() {
  const [todos, setTodos] = useState(initialTodos)

  return (
    <main className="todo-shell">
      <section className="todo-card">
        <p className="eyebrow">AgentHub Demo</p>
        <h1>Team Todo</h1>
        <button onClick={() => setTodos([...todos, '预览并提交'])}>Add task</button>
        <ul>{todos.map((todo) => <li key={todo}>{todo}</li>)}</ul>
      </section>
    </main>
  )
}

const submitTask = (value: string) => {
  const normalized = value.trim()
  if (!normalized) {
    setError('请输入任务内容')
    return
  }
  setTodos((items) => [...items, normalized])
  setDraft('')
  setError(null)
}

